CREATE TABLE COMPANY (
    COM_ID INT,
    NAME VARCHAR(255),
    CITY VARCHAR(255)
);

CREATE TABLE ORDERS (
    ORDER_ID INT,
    COM_ID INT,
    SALES_ID INT,
    ORDER_DATE VARCHAR(255),
    AMOUNT INT
);

